import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Remote MCP","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/remote-mcp.md","filePath":"mcp/remote-mcp.md"}'),r={name:"mcp/remote-mcp.md"};function d(i,e,n,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="remote-mcp" tabindex="-1">Remote MCP <a class="header-anchor" href="#remote-mcp" aria-label="Permalink to &quot;Remote MCP&quot;">​</a></h1><p>Lets hosted AI clients (ChatGPT, Claude.ai, Claude mobile) talk to your Tradeboard install over the internet so you can ask them to fetch quotes, summarise positions, or place orders in plain English.</p><p>Local stdio MCP (Claude Desktop / Cursor / Windsurf on the same machine as your install) keeps working unchanged. Remote MCP is a parallel, opt-in transport that shares the same tool registry but reaches it over HTTPS.</p><table tabindex="0"><thead><tr><th>You want to...</th><th>Use</th></tr></thead><tbody><tr><td>Trade from your laptop using Claude Desktop, Cursor, or Windsurf</td><td><strong>Local stdio</strong> (MCP setup guide)</td></tr><tr><td>Trade from ChatGPT.com, Claude.ai, or the Claude mobile app</td><td><strong>Remote MCP</strong> (this guide)</td></tr><tr><td>Both</td><td>Enable both, they don&#39;t interfere</td></tr></tbody></table><hr><h3 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h3><ol><li><strong>Tradeboard on your own domain with HTTPS.</strong> Dashboard reachable at <code>https://yourdomain.com</code>, login + broker auth + orders all working through the web UI. If you&#39;re not there yet, start with one of the install scripts: <code>install/install.sh</code>, <code>install/install-multi.sh</code>, <code>install/install-docker.sh</code>, or <code>install/install-docker-multi-custom-ssl.sh</code>.</li><li><strong>Tradeboard 2.0.1.0 or later.</strong> The dashboard footer shows the version; <code>GET https://yourdomain.com/auth/app-info</code> returns it as JSON. On older builds run <code>install/update.sh</code> first.</li><li><strong>An Tradeboard API key.</strong> Generate one at <strong>Profile → API Keys</strong>. The MCP server uses it server-side; hosted clients never see it, they get OAuth tokens instead.</li><li><strong>A hosted client account that supports custom MCP connectors.</strong> Check the client&#39;s current plan and workspace requirements; these are controlled by the client vendor.</li></ol><hr><h3 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h3><h4 id="native-install-install-sh" tabindex="-1">Native install (<code>install.sh</code>) <a class="header-anchor" href="#native-install-install-sh" aria-label="Permalink to &quot;Native install (`install.sh`)&quot;">​</a></h4><p>The installer asks at run time whether to enable Remote MCP. If you said <strong>yes</strong>, it&#39;s already on at <code>https://yourdomain.com/mcp</code>, skip to <em>Connecting</em>.</p><p>If you said no and want to flip it now, edit <code>/var/python/tradeboard/.env</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MCP_HTTP_ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;True&#39;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MCP_PUBLIC_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://yourdomain.com&#39;</span></span></code></pre></div><p>Then <code>sudo systemctl restart tradeboard</code>.</p><h4 id="multi-domain-native-install-multi-sh" tabindex="-1">Multi-domain native (<code>install-multi.sh</code>) <a class="header-anchor" href="#multi-domain-native-install-multi-sh" aria-label="Permalink to &quot;Multi-domain native (`install-multi.sh`)&quot;">​</a></h4><p>Edit the per-deploy <code>.env</code> (typically <code>/var/python/tradeboard-flask/&lt;deploy-name&gt;/.env</code>) with the same two keys, then <code>sudo systemctl restart tradeboard-&lt;deploy-name&gt;</code>.</p><h4 id="docker-install-docker-sh-install-docker-multi-custom-ssl-sh" tabindex="-1">Docker (<code>install-docker.sh</code> / <code>install-docker-multi-custom-ssl.sh</code>) <a class="header-anchor" href="#docker-install-docker-sh-install-docker-multi-custom-ssl-sh" aria-label="Permalink to &quot;Docker (`install-docker.sh` / `install-docker-multi-custom-ssl.sh`)&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/tradeboard</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install/enable-remote-mcp-docker.sh</span></span></code></pre></div><p>The helper picks the stack (or asks if you have several), backs up the bind-mounted <code>.env</code>, sets the keys, restarts the container, and probes the OAuth + healthz endpoints. Re-run for each instance.</p><h4 id="defaults-after-enabling" tabindex="-1">Defaults after enabling <a class="header-anchor" href="#defaults-after-enabling" aria-label="Permalink to &quot;Defaults after enabling&quot;">​</a></h4><p>Native installers only turn on <code>MCP_HTTP_ENABLED</code> and set <code>MCP_PUBLIC_URL</code>. They inherit the current <code>.sample.env</code> values: approval is off and write scope is enabled. Review these settings before exposing the service:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MCP_OAUTH_REQUIRE_APPROVAL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;True&#39;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MCP_OAUTH_WRITE_SCOPE_ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;False&#39;</span></span></code></pre></div><p>The <code>enable-remote-mcp-docker.sh</code> helper applies that stricter posture automatically: new clients require approval and Remote MCP starts read-only. It also preserves the default browser allowlist of <code>https://claude.ai,https://chatgpt.com</code>.</p><p>Enable <code>MCP_OAUTH_WRITE_SCOPE_ENABLED=True</code> only after validating read-only sessions and deciding that hosted clients may place or modify orders.</p><hr><h3 id="connecting-using-chatgpt-and-claude" tabindex="-1">Connecting &amp; using ChatGPT and Claude <a class="header-anchor" href="#connecting-using-chatgpt-and-claude" aria-label="Permalink to &quot;Connecting &amp; using ChatGPT and Claude&quot;">​</a></h3><p>Once it&#39;s enabled, your MCP URL is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://yourdomain.com/mcp</span></span></code></pre></div><p>With <code>MCP_OAUTH_REQUIRE_APPROVAL=True</code>, the first connection pauses until you approve the client at <code>/admin/remote-mcp</code>. With approval disabled, registration proceeds immediately; use that setting only on a deliberately restricted deployment.</p><hr><h4 id="adding-tradeboard-to-chatgpt" tabindex="-1">Adding Tradeboard to ChatGPT <a class="header-anchor" href="#adding-tradeboard-to-chatgpt" aria-label="Permalink to &quot;Adding Tradeboard to ChatGPT&quot;">​</a></h4><blockquote><p>Heads up: ChatGPT recently renamed <strong>Connectors → Apps</strong>. Same feature, new menu name. The in-chat menu still says <em>Connectors</em>, so don&#39;t be confused.</p></blockquote><p><strong>Step 1: Open Apps settings</strong></p><ol><li>Avatar (bottom left) → <strong>Settings</strong></li><li>Sidebar → <strong>Apps</strong></li><li>Top right → <strong>Add more</strong> → opens <strong>New App BETA</strong></li></ol><p><strong>Step 2: Fill in the form</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td><code>Tradeboard</code></td></tr><tr><td>Description</td><td><code>Tradeboard trading server</code> (optional)</td></tr><tr><td>MCP Server URL</td><td><code>https://yourdomain.com/mcp</code></td></tr><tr><td>Authentication</td><td><code>OAuth</code></td></tr></tbody></table><p><strong>Step 3: Advanced OAuth settings</strong></p><p>Expand <strong>Advanced OAuth settings</strong> → <strong>Registration method</strong> → <code>Dynamic Client Registration (DCR)</code>.</p><p>The notice <em>&quot;CIMD is unavailable…&quot;</em> is expected, Tradeboard advertises DCR. DCR is the right pick.</p><p>Default scopes ChatGPT requests are <code>read:market read:account</code>. Add <code>write:orders</code> only if you&#39;ve turned <code>MCP_OAUTH_WRITE_SCOPE_ENABLED=True</code> on the server <strong>and</strong> you want this connector to place orders.</p><p><strong>Step 4: Acknowledge and create</strong></p><p>Tick <em>&quot;I understand and want to continue&quot;</em> under the orange warning, then <strong>Create</strong>.</p><p><strong>Step 5: Pending approval (when enabled)</strong></p><p>ChatGPT will show:</p><blockquote><p>OAuth authorization failed: unauthorized_client</p></blockquote><p>This is expected only when <code>MCP_OAUTH_REQUIRE_APPROVAL=True</code>. Your server saw the registration but is holding it until you approve. Don&#39;t dismiss the modal.</p><p><strong>Step 6: Approve in Tradeboard</strong></p><ol><li>New tab → <code>https://yourdomain.com/admin/remote-mcp</code></li><li>Sign in (TOTP if MCP 2FA is on)</li><li><strong>Pending approvals</strong> → verify name + timestamp match → <strong>Approve</strong></li></ol><p><strong>Step 7: Complete OAuth</strong></p><ol><li>Back in ChatGPT → <strong>Reconnect</strong></li><li>A tab pops to <code>https://yourdomain.com/oauth/authorize?...</code></li><li>Sign in if needed → consent screen lists scopes (verify the redirect URI is a <code>chatgpt.com</code> URL) → <strong>Authorize</strong></li><li>App moves from Drafts to Enabled</li></ol><p><strong>Step 8: Use it</strong></p><p>In any new chat, click <strong>+</strong> below the message box → <strong>Connectors</strong> → toggle <strong>Tradeboard</strong> ON.</p><p>Try:</p><blockquote><p><em>&quot;Using Tradeboard, give me the LTP of RELIANCE on NSE.&quot;</em></p></blockquote><p>ChatGPT calls <code>get_quote</code> and shows the price. With <code>read:account</code> granted, also try:</p><blockquote><p><em>&quot;What&#39;s my account balance and current open positions?&quot;</em></p></blockquote><p><strong>Client policy and tool availability</strong></p><p>Tradeboard exposes tools allowed by the granted OAuth scopes. ChatGPT can apply additional product policy, confirmation, plan, and connector restrictions, so the tools visible or executable in a client can differ from the server&#39;s <code>tools/list</code> response. Verify sensitive operations in Analyzer Mode and do not treat a granted <code>write:orders</code> scope as a guarantee that a hosted client will execute every write tool.</p><p><strong>Useful ChatGPT prompts</strong></p><ul><li><em>&quot;Get me the bid-ask spread for INFY and HDFCBANK&quot;</em></li><li><em>&quot;Summarise my holdings and tell me which are in profit&quot;</em></li><li><em>&quot;Pull 1-day candles for SBIN for the last 30 days and tell me the trend&quot;</em></li><li><em>&quot;List my orders from today and show fills vs rejects&quot;</em></li></ul><hr><h4 id="adding-tradeboard-to-claude-ai" tabindex="-1">Adding Tradeboard to Claude.ai <a class="header-anchor" href="#adding-tradeboard-to-claude-ai" aria-label="Permalink to &quot;Adding Tradeboard to Claude.ai&quot;">​</a></h4><p><strong>Step 1: Connectors page</strong></p><p>claude.ai → name (bottom left) → <strong>Settings</strong> → <strong>Connectors</strong>.</p><p><strong>Step 2: Add custom</strong></p><p>Top right <strong>+</strong> → <strong>Add custom connector</strong>.</p><p><strong>Step 3: Fill in</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td><code>Tradeboard</code></td></tr><tr><td>Remote MCP server URL</td><td><code>https://yourdomain.com/mcp</code></td></tr></tbody></table><p>Leave <strong>Advanced settings</strong> alone, OAuth is detected automatically. Click <strong>Add</strong>.</p><p><strong>Step 4: Pending approval (when enabled)</strong></p><p>When <code>MCP_OAUTH_REQUIRE_APPROVAL=True</code>, the first attempt fails with a pending-approval error. Keep the page open. With approval disabled, continue directly to OAuth consent.</p><p><strong>Step 5: Approve in Tradeboard</strong></p><p><code>https://yourdomain.com/admin/remote-mcp</code> → <strong>Pending approvals</strong> → <strong>Approve</strong>.</p><p><strong>Step 6: Complete OAuth</strong></p><p>Back in claude.ai → <strong>Connect</strong> on the connector card → sign in to Tradeboard (+ TOTP if on) → consent screen (verify redirect URI is <code>claude.ai</code>) → <strong>Authorize</strong>. Card switches to <strong>Disconnect</strong> when you&#39;re live.</p><p><strong>Step 7: Tool permissions</strong></p><p>Click your <strong>Tradeboard</strong> connector to expand permissions:</p><table tabindex="0"><thead><tr><th>Group</th><th>Recommendation</th></tr></thead><tbody><tr><td>Interactive tools (<code>place_order</code>, <code>modify_order</code>, <code>cancel_order</code>, ...)</td><td><strong>Ask me</strong> at first; <strong>Always allow</strong> once you trust the prompts</td></tr><tr><td>Read-only tools</td><td><strong>Always allow</strong></td></tr><tr><td>App-only tools</td><td><strong>Always allow</strong></td></tr></tbody></table><p>You can override individual tools, e.g. <em>Always allow</em> most things but force <em>Ask me</em> for <code>cancel_all_orders</code>.</p><p><strong>Step 8: Use it</strong></p><p>In any chat, click the <strong>Tools</strong> icon below the message box → toggle <strong>Tradeboard</strong> on.</p><blockquote><p><em>&quot;Show me the current LTP of NIFTY 50 and a quick view of my open positions.&quot;</em></p></blockquote><p>Claude shows expandable tool-call cards. <em>Ask me</em> tools surface a permission prompt with <strong>Allow once / Always allow / Deny</strong>.</p><p><strong>Client policy and tool availability</strong></p><p>Tradeboard exposes the same scoped registry to Claude.ai, but Claude can apply client-side permissions, plan limits, confirmations, or policy restrictions. Check the connector&#39;s current tool list and require confirmation for destructive operations.</p><p><strong>Recommended posture for write tools</strong></p><ul><li>Start in <strong>Sandbox / Analyzer mode</strong> (<code>/analyzer</code>) and dry-run prompts before turning live trading on</li><li>Keep <strong>MCP 2FA</strong> on, fresh authorization for <code>write:orders</code> then requires TOTP</li><li>Set a tight <code>MCP_RATE_LIMIT_WRITE</code> (e.g. <code>5 per minute</code>) so a runaway model can&#39;t fire a flurry of orders before you intervene</li><li>Tail <code>log/mcp.jsonl</code> while testing, every call recorded with timestamp, scope, outcome, latency</li><li>Keep the <strong>Kill switch</strong> at <code>/admin/remote-mcp</code> one click away</li></ul><p><strong>Useful Claude prompts</strong></p><ul><li><em>&quot;Place a limit BUY for 1 share of TCS at ₹3500 in CNC product on NSE&quot;</em></li><li><em>&quot;Modify my last open INFY order, change the quantity to 5&quot;</em></li><li><em>&quot;Cancel all my open orders&quot;</em></li><li><em>&quot;What was my P&amp;L today?&quot;</em></li></ul><p>For more example prompts per tool, see the Tool References, the same prompts work on Remote MCP.</p><hr><h3 id="switching-scopes-after-connecting" tabindex="-1">Switching scopes after connecting <a class="header-anchor" href="#switching-scopes-after-connecting" aria-label="Permalink to &quot;Switching scopes after connecting&quot;">​</a></h3><p>Already connected with <code>read:market read:account</code> and want to add <code>write:orders</code>?</p><ol><li>Set <code>MCP_OAUTH_WRITE_SCOPE_ENABLED=True</code> in <code>.env</code> and restart</li><li><strong>Disconnect</strong> the connector / app in ChatGPT or Claude</li><li>Re-add it with the broader scope set</li><li>Re-approve at <code>/admin/remote-mcp</code></li></ol><p>OAuth doesn&#39;t let an existing token widen its scope, re-consent is required. By design.</p><hr><h3 id="daily-operations" tabindex="-1">Daily operations <a class="header-anchor" href="#daily-operations" aria-label="Permalink to &quot;Daily operations&quot;">​</a></h3><h4 id="admin-remote-mcp" tabindex="-1"><code>/admin/remote-mcp</code> <a class="header-anchor" href="#admin-remote-mcp" aria-label="Permalink to &quot;`/admin/remote-mcp`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Section</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><strong>Pending approvals</strong></td><td>New clients land here. Approve only ones you recognise, the name is set by the hosted client itself</td></tr><tr><td><strong>Approved clients</strong></td><td>Currently authorised. Each row shows last-used time</td></tr><tr><td><strong>Revoked clients</strong></td><td>Permanent. There is no un-revoke. The client must register again through DCR for a new <code>client_id</code></td></tr><tr><td><strong>MCP tool call audit</strong></td><td>Every tool call: timestamp, client, tool, scope, outcome, latency. Filter by tool or outcome</td></tr><tr><td><strong>Kill switch</strong></td><td>Revokes every live refresh token in the system, not only those of approved clients. Existing access JWTs remain valid until their short expiry</td></tr></tbody></table><h4 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h4><p>Same data as the admin page, written to <code>log/mcp.jsonl</code> as JSON Lines. Tail with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log/mcp.jsonl</span></span></code></pre></div><p>Tool <strong>arguments are hashed</strong>, not stored verbatim, so the log itself is not a data leak.</p><h4 id="_2fa-enforcement" tabindex="-1">2FA enforcement <a class="header-anchor" href="#_2fa-enforcement" aria-label="Permalink to &quot;2FA enforcement&quot;">​</a></h4><p>Profile → TOTP → <strong>2FA Enforcement</strong> lets you gate three independent purposes:</p><table tabindex="0"><thead><tr><th>Purpose</th><th>What it gates</th></tr></thead><tbody><tr><td>Dashboard sign-in</td><td>TOTP after password on every login</td></tr><tr><td>Remote MCP authorization</td><td>Fresh TOTP at <code>/oauth/authorize</code> for every <code>write:orders</code> grant</td></tr><tr><td>Password reset</td><td>Forces TOTP path (no email fallback)</td></tr></tbody></table><p>All three default off so existing installs see no change. Saving requires a fresh TOTP code in the same request, proves you have authenticator access for both enabling and disabling.</p><hr><h3 id="configuration-reference" tabindex="-1">Configuration reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration reference&quot;">​</a></h3><p>All keys live in <code>.env</code> (native) or the bind-mounted <code>.env</code> (Docker). Native installers set the master switch and public URL; the dedicated Docker helper also applies the stricter approval and write-scope settings described above.</p><table tabindex="0"><thead><tr><th>Key</th><th>Sample default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>MCP_HTTP_ENABLED</code></td><td><code>False</code></td><td>Master switch</td></tr><tr><td><code>MCP_PUBLIC_URL</code></td><td>empty; required when enabled</td><td>Public HTTPS origin advertised in OAuth metadata</td></tr><tr><td><code>MCP_OAUTH_REQUIRE_APPROVAL</code></td><td><code>False</code></td><td>New clients require admin approval when enabled</td></tr><tr><td><code>MCP_OAUTH_WRITE_SCOPE_ENABLED</code></td><td><code>True</code></td><td>Whether <code>write:orders</code> is grantable at all</td></tr><tr><td><code>MCP_HTTP_CORS_ORIGINS</code></td><td><code>https://claude.ai,https://chatgpt.com</code></td><td>Browser allowlist</td></tr><tr><td><code>MCP_HTTP_IP_ALLOWLIST</code></td><td>empty</td><td>Present in <code>.sample.env</code> but <strong>not implemented</strong>. Setting it has no effect; use the reverse proxy or firewall for IP filtering</td></tr><tr><td><code>MCP_OAUTH_ACCESS_TTL</code></td><td><code>900</code></td><td>Access-token TTL in seconds (max 3600)</td></tr><tr><td><code>MCP_OAUTH_REFRESH_TTL</code></td><td><code>2592000</code></td><td>Refresh-token TTL in seconds (30 days; min 3600, max 31 days)</td></tr><tr><td><code>MCP_OAUTH_CODE_TTL</code></td><td><code>60</code></td><td>Authorization-code TTL (max 300)</td></tr><tr><td><code>MCP_RATE_LIMIT_READ</code></td><td><code>60 per minute</code></td><td>Per-token cap for read scopes</td></tr><tr><td><code>MCP_RATE_LIMIT_WRITE</code></td><td><code>50 per minute</code></td><td>Per-token cap for <code>write:orders</code></td></tr><tr><td><code>MCP_LOOPBACK_URL</code></td><td>inherits <code>HOST_SERVER</code></td><td>Override only for unusual topologies</td></tr><tr><td><code>MCP_OAUTH_KEYS_DIR</code></td><td><code>keys</code></td><td>Directory for RS256 signing keys</td></tr><tr><td><code>TRADEBOARD_MCP_READ_ONLY</code></td><td>off</td><td>Drops all 11 order tools from the registry, leaving 37. Survives an already-granted <code>write:orders</code> scope</td></tr><tr><td><code>TRADEBOARD_MCP_TOOLSETS</code></td><td>all</td><td>Comma-separated subset of <code>orders</code>, <code>account</code>, <code>marketdata</code>, <code>research</code>, <code>utility</code></td></tr><tr><td><code>TRADEBOARD_MCP_TRUST_ENVELOPE</code></td><td><code>1</code></td><td>Set to <code>0</code> to return bare payloads instead of the trust envelope</td></tr></tbody></table><p>The last three apply to both the stdio and HTTP transports.</p><hr><h3 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h3><p>The defenses, in plain order:</p><ol><li><strong>Optional approval gate</strong>: with <code>MCP_OAUTH_REQUIRE_APPROVAL=True</code>, clients cannot complete OAuth until you approve them at <code>/admin/remote-mcp</code></li><li><strong>Scope gate</strong>: <code>write:orders</code> is invisible in OAuth discovery when <code>MCP_OAUTH_WRITE_SCOPE_ENABLED=False</code></li><li><strong>Short access tokens</strong>: 15-minute TTL caps the damage window if a token is stolen</li><li><strong>Rate limits</strong>: per-token, separately for reads and writes</li><li><strong>PKCE + JWT</strong>: S256-only PKCE, exact redirect_uri matching, signed access JWTs, and rotating refresh tokens</li><li><strong>Refresh-token family protection</strong>: reuse of an already-rotated refresh token revokes its entire token family</li><li><strong>Kill switch</strong>: one click revokes all refresh tokens; already-issued access JWTs remain valid until expiry</li><li><strong>Read-only mode</strong>: <code>TRADEBOARD_MCP_READ_ONLY</code> removes every order tool from the registry, so even a client already holding <code>write:orders</code> cannot place an order</li></ol><p><code>send_telegram_alert</code> is the one exception to &quot;read scopes cannot cause an effect outside Tradeboard&quot;. It is annotated as a write tool but gated on <code>read:account</code>, so a read-only hosted session can still send outbound Telegram messages.</p><blockquote><p><strong>The blast radius is real.</strong> A stolen access token can place orders the broker accepts; they originate from your registered server IP. The 15-minute default TTL limits the window, but the kill switch does not immediately invalidate an access JWT. Never combine <code>MCP_OAUTH_WRITE_SCOPE_ENABLED=True</code> with <code>MCP_OAUTH_REQUIRE_APPROVAL=False</code> on a public deployment: that lets any internet client register, auto-approve, and request order scope.</p></blockquote><p>For the implementation boundaries behind these controls, see <a href="./../developers/design-documentation/41-mcp-architecture">MCP Architecture</a>.</p><hr><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>unauthorized_client</code> after Create / Add</td><td>DCR client not approved yet</td><td>Approve at <code>/admin/remote-mcp</code></td></tr><tr><td><code>invalid_client</code> on retry</td><td>Client revoked or DB reset; old <code>client_id</code> cached</td><td>Disconnect + re-add to force fresh DCR</td></tr><tr><td><em>&quot;Server doesn&#39;t implement OAuth&quot;</em></td><td>Old build</td><td>Update to 2.0.1.0+</td></tr><tr><td><em>&quot;CIMD is unavailable&quot;</em> in ChatGPT</td><td>Tradeboard advertises DCR, not CIMD</td><td>Expected: pick <strong>DCR</strong></td></tr><tr><td>Tools missing from chat</td><td>Connector not toggled on for that chat</td><td><code>+</code> menu (ChatGPT) or Tools menu (Claude)</td></tr><tr><td><code>bad_arguments</code> on a tool call</td><td>Hosted client guessed parameter names</td><td>Update Tradeboard (newer builds expose strict tool schemas)</td></tr><tr><td>Sudden 401 on every call</td><td>Refresh token expired or kill switch fired</td><td><strong>Reconnect</strong> on the connector</td></tr><tr><td><code>place_order</code> blocked on ChatGPT</td><td>OpenAI&#39;s safety policy</td><td>Use Claude.ai for order placement</td></tr><tr><td><em>&quot;Failed to connect to the server&quot;</em> on tool calls</td><td>Loopback misconfigured</td><td>Confirm <code>HOST_SERVER</code> in <code>.env</code> matches your dashboard URL; restart</td></tr><tr><td>Tokens issued but <code>/mcp</code> returns 401</td><td><code>MCP_PUBLIC_URL</code> changed after the tokens were minted, or the tokens came from a different instance</td><td>Tokens carry <code>iss</code>/<code>aud</code> derived from <code>MCP_PUBLIC_URL</code> at issue time and are checked against the server&#39;s current value. Keep the value stable, or reconnect the client after changing it</td></tr><tr><td>Form submit blocked by CSP</td><td>Old build</td><td>Update to 2.0.1.0+</td></tr><tr><td>Container won&#39;t restart after enabler</td><td>Bad <code>.env</code> change</td><td>Run the rollback one-liner the enabler printed; restart; check <code>log/errors.jsonl</code></td></tr></tbody></table><hr><h3 id="subdomain-mode-advanced" tabindex="-1">Subdomain mode (advanced) <a class="header-anchor" href="#subdomain-mode-advanced" aria-label="Permalink to &quot;Subdomain mode (advanced)&quot;">​</a></h3><p>If you want MCP on a separate hostname (e.g. <code>mcp.yourdomain.com</code>) so its cookies, CORS, and TLS lifecycle are isolated from the dashboard, the manual recipe is in <code>install/Remote-MCP-readme.md</code>. Same nginx + certbot pattern as <code>install-docker-multi-custom-ssl.sh</code>. Most users don&#39;t need this; same-domain is what the installer automates.</p><hr><h3 id="disabling" tabindex="-1">Disabling <a class="header-anchor" href="#disabling" aria-label="Permalink to &quot;Disabling&quot;">​</a></h3><p>Native:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;s|MCP_HTTP_ENABLED.*|MCP_HTTP_ENABLED = &#39;False&#39;|&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/python/tradeboard/.env</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tradeboard</span></span></code></pre></div><p>(<code>install-multi.sh</code> users: substitute the per-deploy <code>.env</code> and service name.)</p><p>Docker:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;s|MCP_HTTP_ENABLED.*|MCP_HTTP_ENABLED = &#39;False&#39;|&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/tradeboard/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">domai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.env</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/tradeboard/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">domai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><p>OAuth + MCP routes immediately stop responding. Existing tokens hit 404. <strong>Local stdio MCP is unaffected</strong>: it runs over stdin/stdout and doesn&#39;t touch the HTTP transport.</p><p>For a softer takedown that keeps Remote MCP enabled, visit <code>/admin/remote-mcp</code> → <strong>Kill switch</strong>. It revokes refresh tokens, so hosted clients must complete OAuth again after their current access JWT expires. To stop access immediately, disable Remote MCP and restart the application.</p><hr><h3 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h3><ul><li>MCP Server Setup Guide: local stdio integration with Claude Desktop / Cursor / Windsurf</li><li>Tool References: every tool with parameters and example prompts (shared across both transports)</li><li>Tradeboard Symbol Format: how equity / future / option symbols are constructed</li><li><code>install/Remote-MCP-readme.md</code>: operator-focused install + threat model in the source tree</li><li><a href="./../developers/design-documentation/41-mcp-architecture">MCP Architecture</a>: transport and OAuth implementation boundaries</li></ul><hr><hr>',139)])])}const g=t(r,[["render",d]]);export{u as __pageData,g as default};
